2	//
3	// Bump the site version for a production release.
4	//
5	// Scheme: 1.<mmdd>.<previous patch + 1>
6	//   - major  stays 1
7	//   - minor  is the release date as zero-padded month+day (Asia/Jerusalem, the
8	//            timezone the rest of the fleet stamps its builds in)
9	//   - patch  is a monotonic counter: previous patch + 1, so it always advances
10	//            even when the day (and therefore the minor) rolls over
11	//
12	// package.json is the single source of truth for the version. The deploy
13	// workflow runs this, then commits the bumped file back to main — so the number
14	// in the repo always names the last release that actually went out.
15	//
16	// Prints the new version to stdout (nothing else) so the workflow can capture it.
17	import { readFileSync, writeFileSync } from "node:fs";
18	import { fileURLToPath } from "node:url";
19	import { dirname, join } from "node:path";
20	
21	const pkgPath = join(dirname(fileURLToPath(import.meta.url)), "..", "package.json");
22	const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
23	
24	// The current patch is the third dotted component; treat anything unparseable
25	// (e.g. the initial "1.0.0") as 0 so the first bump lands on patch 1.
26	const prevPatch = Number.parseInt(String(pkg.version ?? "").split(".")[2], 10);
27	const newPatch = (Number.isFinite(prevPatch) ? prevPatch : 0) + 1;
28	
29	const parts = new Intl.DateTimeFormat("en-CA", {
30	  timeZone: "Asia/Jerusalem", month: "2-digit", day: "2-digit",
31	}).formatToParts(new Date());
32	const mm = parts.find((p) => p.type === "month").value;
33	const dd = parts.find((p) => p.type === "day").value;
